def scope_build(b, scope_template_ref, dest):
    s=doc(scope_template_ref)
    for k in ('run_uuid','new_output_root','new_wrapper_root','new_export_root','new_authorization_root','new_grant_preflight_root',
              'registration_namespace','runtime_resources_ref','compiler_resources_ref','current43_authority_ref',
              'controller_review_path','main_git','public_environment','authorization_gate_ref','runner_ref','launcher_ref'):
        need(b.get(k) is not None,'explicit scope field '+k); s[k]=b[k]
    s.update(preparation_only=False,execution_authorized=True,expected_before_registration=b['before'],
             expected_registration=b['after'],registration_metadata_paths=CANON[:2])
    need(s['source_commit']==SOURCE and s['ordered_cases']==['real-existing-open-readonly','real-existing-self-send'],'fixed source/roster')
    return save(dest,s)
